(function () {
  "use strict";

  // The hero animation is a welcome, not a spinner: it runs once and then holds
  // still so nothing on a page the user reads keeps moving. A GIF cannot be
  // stopped from script and it cannot be photographed either -- browsers hand
  // back its first frame, not the one on screen -- so holding it means swapping
  // in a still of the frame the animation reaches at the cutoff. That still is
  // generated by tools/freeze_frame.py; change HOLD_MS and the still stops
  // matching the animation until the script is re-run with the same --at.
  var HOLD_MS = 1600;

  var image = document.getElementById("home-hero-animation");
  if (!image) {
    return;
  }

  var animatedSrc = image.getAttribute("src");
  var stillSrc = image.getAttribute("data-still-src");
  if (!stillSrc) {
    return;
  }

  var timer = null;

  // Fetched up front because the swap has to be instant: waiting on the network
  // at the cutoff would blank the hero at the moment it is meant to settle.
  var preload = new Image();
  preload.src = stillSrc;

  function hold() {
    image.src = stillSrc;
  }

  function arm() {
    window.clearTimeout(timer);
    // The GIF starts animating when it is decoded, not when this script runs,
    // so a load that is still in flight gets the countdown started for it.
    if (image.complete) {
      timer = window.setTimeout(hold, HOLD_MS);
    } else {
      image.addEventListener("load", arm, { once: true });
    }
  }

  arm();

  // A back/forward restore hands back the page exactly as it was left, held
  // frame included. Restoring the GIF gives that arrival the same run of
  // animation as a fresh load.
  window.addEventListener("pageshow", function (event) {
    if (!event.persisted) {
      return;
    }
    image.src = animatedSrc;
    arm();
  });
})();
